};

struct ConceptDriftTableResult {
  std::vector<EventTable> returned_tables;
  std::vector<double> change_timestamps;
  std::vector<double> p_values;
};

struct DecomposedAlignmentMove {
  std::optional<std::string> log;
  std::optional<std::string> model;
  std::size_t transition = static_cast<std::size_t>(-1);
  [[nodiscard]] bool synchronous() const noexcept {
    return log && model && *log != ">>" && *model != ">>" && *log == *model;
  }
};

struct DecomposedAlignmentOptions {
  DecomposedAlignmentVariant variant = DecomposedAlignmentVariant::kRecomposMaximal;
  double threshold_border_agreement = 100000000.0;
  double max_time_trace = 0.0;
  double max_time_total = 0.0;
  std::size_t max_states = 200000;
  std::size_t max_total_states = 2000000;
  bool use_cache = true;
  bool clear_cache = false;
  // Standard costs.
  double log_move_cost = 10000.0;
  double model_move_cost = 10000.0;
  double tau_model_cost = 1.0;
  double sync_cost = 0.0;
  std::unordered_map<std::string, double> activity_log_costs;
  std::unordered_map<std::string, double> activity_model_costs;
  std::unordered_map<std::string, double> activity_sync_costs;
  std::vector<std::size_t> initial_marking;
  std::vector<std::size_t> final_marking;
  // Event field used to construct alignment words.
  std::string activity_attribute = "concept:name";
};

struct DecomposedAlignmentTrace {
  std::vector<std::string> activities;
  std::uint64_t count = 1;
  bool complete = false;
  bool timed_out = false;
  bool exhausted = false;
  double cost = 0.0;
  double fitness = 0.0;
  double best_worst_cost = 0.0;
  std::vector<DecomposedAlignmentMove> alignment;
};

struct DecomposedAlignmentDiagnostics {
  std::size_t decompositions = 0;
  std::size_t components = 0;
  std::size_t merges = 0;
  std::size_t cache_hits = 0;
  std::size_t cache_misses = 0;
  std::size_t border_disagreements = 0;
  std::size_t agreement_iterations = 0;
  std::size_t visited_states = 0;
  std::size_t queued_states = 0;
  std::size_t traversed_arcs = 0;
  bool whole_net_fallback = false;
  std::string note;
};

struct DecomposedAlignmentResult {
  bool complete = true;
  bool timed_out = false;
  bool exhausted = false;
  double fitness = 1.0;
  double best_worst_cost = 0.0;
  std::uint64_t trace_count = 0;
  double total_cost = 0.0;
  DecomposedAlignmentDiagnostics diagnostics;
  std::vector<DecomposedAlignmentTrace> traces;
  // One row per source trace, including duplicate variants.
  [[nodiscard]] const std::vector<DecomposedAlignmentTrace>& alignments() const noexcept {
    return traces;
  }
};

struct DfgAlignmentMove {
  std::string log;    // ">>" denotes a move on model
  // ">>" denotes a move on log. CLASSIC can expose an early sink transition;
  // its generated identity is canonicalized to "@@dfg_sink", appending '_'
  // until the name differs from every model and trace activity.
  std::string model;
};

struct DfgAlignmentOptions {
  DfgAlignmentVariant variant = DfgAlignmentVariant::kClassic;
  std::map<std::string, double> sync_cost;
  std::map<std::string, double> model_move_cost;
  std::map<std::string, double> log_move_cost;
  std::map<std::string, double> internal_log_move_cost;
  std::size_t max_visited_states = 0;  // zero means unlimited
  std::uint64_t max_time_ms = 0;       // zero means unlimited
  // Event fields used when converting traces to DFG alignment words and when
  // materializing projected logs.  The conventional aliases resolve to the
  // first-class Event projections; other names resolve to generic attributes.
  std::string activity_attribute = "concept:name";
  std::string timestamp_attribute = "time:timestamp";
  // Nonempty maps are always supplied. These flags distinguish an explicitly
  // empty cost function from an omitted function that receives default costs.
  bool sync_cost_supplied = false;
  bool model_move_cost_supplied = false;
  bool log_move_cost_supplied = false;
  bool internal_log_move_cost_supplied = false;
};

struct DfgAlignmentResult {
  std::vector<DfgAlignmentMove> alignment;
  double cost = 0.0;
  double internal_cost = 0.0;
  // Only log alignment computes fitness and best/worst cost. Raw trace
  // alignment leaves both as NaN, matching the reference's absent fields.
  double fitness = 1.0;
  double best_worst_cost = 0.0;
  std::size_t visited_states = 0;
  std::size_t closed = 0;
  std::size_t closed_states = 0;
  // False when the supplied graph has no accepting path. Scores are undefined.
  bool computed = true;
};

struct DfgAlignmentLogResult {
  std::vector<DfgAlignmentResult> alignments;
  // Number of unique variants searched (useful to observe caching).
